import numpy as np
emb = {  # 손으로 만든 3차원 장난감 임베딩: [왕족, 성별(+남), 동물]
    "king":  np.array([0.9,  0.8, 0.0]), "queen": np.array([0.9, -0.8, 0.0]),
    "man":   np.array([0.1,  0.8, 0.0]), "woman": np.array([0.1, -0.8, 0.0]),
    "dog":   np.array([0.0,  0.1, 0.9]), "cat":   np.array([0.0, -0.1, 0.9]),
}
def cos(a, b):
    return a @ b / (np.linalg.norm(a) * np.linalg.norm(b))
def nearest(vec, exclude=()):
    scores = {w: cos(vec, v) for w, v in emb.items() if w not in exclude}
    return sorted(scores.items(), key=lambda kv: -kv[1])[:3]
print(nearest(emb["dog"], exclude={"dog"}))
q = emb["king"] - emb["man"] + emb["woman"]   # 유추: king - man + woman
print(q, nearest(q, exclude={"king", "man", "woman"}))
